const hours = ["子", "丑", "寅", "卯", "辰", "巳", "午", "未", "申", "酉", "戌", "亥"]

function side(name: string, score: number) {
  return { team: { name }, score }
}

function match(id: string, home: string, away: string): Match {
  return {
    id,
    home: side(home, 2),
    away: side(away, 1),
    winner: "home",
    status: "finished",
  }
}

const rounds: Round[] = [
  {
    name: "四分之一决赛",
