import { fireEvent, render, renderHook } from "@testing-library/react"
import { useRef, type RefObject } from "react"
import { expect, test, vi } from "vitest"

import { useDismiss } from "./use-dismiss"
import { useHoverGesture } from "./use-hover-gesture"
import { useTapGesture } from "./use-tap-gesture"

test("鼠标进入算悬停，触屏进入不算", () => {
  const { result } = renderHook(() => useHoverGesture())
  expect(result.current.enter({ pointerId: 1, pointerType: "mouse", buttons: 0 })).toBe(true)
  expect(result.current.enter({ pointerId: 2, pointerType: "touch", buttons: 1 })).toBe(false)
})

test("start 记下这次点击，take 取走之后为空", () => {
  const { result } = renderHook(() => useTapGesture<string>())
  result.current.start({ pointerType: "mouse" }, "open")
  expect(result.current.take()).toEqual({ pointerType: "mouse", state: "open" })
  expect(result.current.take()).toBeNull()
})

function DismissHost({
  open,
  onDismiss,
}: {
  open: boolean
  onDismiss: () => void
}) {
  const ref = useRef<HTMLDivElement>(null)
  useDismiss(open, onDismiss, ref as RefObject<HTMLElement | null>)
  return <div ref={ref}>面板</div>
}

test("打开时按 Esc 关闭，关上时不关闭", () => {
  const onDismiss = vi.fn()
  const view = render(<DismissHost open onDismiss={onDismiss} />)
  fireEvent.keyDown(window, { key: "Escape" })
  expect(onDismiss).toHaveBeenCalledOnce()

  onDismiss.mockClear()
  view.rerender(<DismissHost open={false} onDismiss={onDismiss} />)
  fireEvent.keyDown(window, { key: "Escape" })
  expect(onDismiss).not.toHaveBeenCalled()
})

// @vitest-environment jsdom

import { act, cleanup, render, screen } from "@testing-library/react"
import { useRef, type RefObject } from "react"
import { afterEach, expect, test, vi } from "vitest"

import { useAnimationActive } from "./use-animation-active"

type Hit = { isIntersecting: boolean }

let hits: ((entries: Hit[]) => void) | undefined
let observed: Element | undefined
let disconnects = 0

class FakeObserver {
  constructor(callback: (entries: Hit[]) => void) {
    hits = callback
  }

  observe(node: Element) {
    observed = node
  }

  disconnect() {
    disconnects += 1
  }
}

function Probe({ target }: { target?: RefObject<Element | null> }) {
  const own = useRef<HTMLDivElement>(null)
  const active = useAnimationActive(target ?? own)
  return (
    <div ref={own} data-testid="node">
      {active ? "播放" : "暂停"}
    </div>
  )
}

function setVisible(visible: boolean) {
  Object.defineProperty(document, "visibilityState", {
    configurable: true,
    get: () => (visible ? "visible" : "hidden"),
  })
  document.dispatchEvent(new Event("visibilitychange"))
}

afterEach(() => {
  cleanup()
  hits = undefined
  observed = undefined
  disconnects = 0
  vi.unstubAllGlobals()
})

test("视口内且标签页可见时播放，离开或隐藏时暂停", () => {
  vi.stubGlobal("IntersectionObserver", FakeObserver)
  setVisible(true)
  render(<Probe />)

  expect(screen.getByText("暂停")).toBeTruthy()
  expect(observed).toBe(screen.getByTestId("node"))

  act(() => {
    hits?.([{ isIntersecting: true }])
  })
  expect(screen.getByText("播放")).toBeTruthy()

  act(() => {
    setVisible(false)
  })
  expect(screen.getByText("暂停")).toBeTruthy()

  act(() => {
    setVisible(true)
  })
  expect(screen.getByText("播放")).toBeTruthy()

  act(() => {
    hits?.([{ isIntersecting: false }])
  })
  expect(screen.getByText("暂停")).toBeTruthy()
})

test("没有观察器或目标时保持暂停，卸载时断开观察", () => {
  vi.stubGlobal("IntersectionObserver", undefined)
  setVisible(true)
  const { unmount } = render(<Probe />)
  expect(screen.getByText("暂停")).toBeTruthy()
  unmount()

  vi.stubGlobal("IntersectionObserver", FakeObserver)
  const empty = { current: null }
  const hidden = render(<Probe target={empty} />)
  expect(screen.getByText("暂停")).toBeTruthy()
  expect(observed).toBeUndefined()

  hidden.unmount()
  const mounted = render(<Probe />)
  expect(observed).toBeTruthy()
  mounted.unmount()
  expect(disconnects).toBeGreaterThan(0)
})

"use client"

import { useEffect, useState, useSyncExternalStore, type RefObject } from "react"

function subscribe(onStoreChange: () => void) {
  document.addEventListener("visibilitychange", onStoreChange)
  return () => document.removeEventListener("visibilitychange", onStoreChange)
}

function visibleNow() {
  return document.visibilityState === "visible"
}

export function useAnimationActive(ref: RefObject<Element | null>) {
  const visible = useSyncExternalStore(subscribe, visibleNow, () => false)
  const [inView, setInView] = useState(false)

  useEffect(() => {
    const node = ref.current
    if (!node || typeof IntersectionObserver === "undefined") return
    const observer = new IntersectionObserver((entries) => {
      const entry = entries[entries.length - 1]
      setInView(entry?.isIntersecting ?? false)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [ref])

  return visible && inView
