  { title: "Silk", tint: "#22d3ee" },
  { title: "Globe", tint: "#f472b6" },
  { title: "Bento", tint: "#f59e0b" },
  { title: "Dock", tint: "#34d399" },
  { title: "Beam", tint: "#818cf8" },
  { title: "Tilt", tint: "#fb7185" },
  { title: "Orbit", tint: "#38bdf8" },
