            ))}
          </div>
        </LayoutGroup>
        {filtered.length === 0 ? <p className="text-sm text-muted-foreground">没有匹配的集成。</p> : null}
        {filtered.length > 6 && !expanded ? (
          <button type="button" className="mt-3 text-sm underline" onClick={() => setExpanded(true)}>查看更多</button>
        ) : null}
      </div>
    </section>
  )
}

